/**
 * Inline @font-face declarations for the two webfonts used in Sportrail
 * templates: Bebas Neue 400 and DM Sans 400/500/700.
 *
 * The woff2 binaries are base64-embedded so HTML rendered by Playwright
 * does NOT need to fetch fonts from fonts.gstatic.com. This eliminates a
 * common cause of slow/failed renders when the CDN is throttled or when
 * networkidle never fires.
 *
 * DM Sans is a variable font: weights 400/500/700 share a single binary,
 * so we declare three @font-face entries pointing at the same data URI.
 *
 * Coverage: Latin (U+0000-00FF) only. This includes Portuguese accented
 * characters (á, é, í, ó, ú, ã, õ, ç, etc.). Eastern European or other
 * scripts would need the latin-ext variant added.
 *
 * Total size: ~67 KB base64 (~50 KB raw). Negligible for a serverless
 * response that is going to ship a multi-MB PNG anyway.
 *
 * Source: Google Fonts CSS API
 *   - bebasneue/v16 latin
 *   - dmsans/v17 latin
 */

const BEBAS_400 =
  "";

const DM_SANS_VARIABLE =
  "";

export const FONTS_INLINE_STYLE = `<style>
@font-face {
  font-family: 'Bebas Neue';
  font-style: normal;
  font-weight: 400;
  font-display: block;
  src: url(data:font/woff2;base64,${BEBAS_400}) format('woff2');
}
@font-face {
  font-family: 'DM Sans';
  font-style: normal;
  font-weight: 400;
  font-display: block;
  src: url(data:font/woff2;base64,${DM_SANS_VARIABLE}) format('woff2');
}
@font-face {
  font-family: 'DM Sans';
  font-style: normal;
  font-weight: 500;
  font-display: block;
  src: url(data:font/woff2;base64,${DM_SANS_VARIABLE}) format('woff2');
}
@font-face {
  font-family: 'DM Sans';
  font-style: normal;
  font-weight: 700;
  font-display: block;
  src: url(data:font/woff2;base64,${DM_SANS_VARIABLE}) format('woff2');
}
</style>`;
